css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx [data-z] div,.dcx [data-z] span,.dcx [data-z] a,.dcx [data-h1]{white-space:nowrap}
.dcx [data-z] p,.dcx [data-z] p *,.dcx [data-z] h2,.dcx [data-z] h2 *,.dcx [data-z] [data-wrap],.dcx [data-z] [data-wrap] *{white-space:normal}
@media (max-width:1040px){.dcx [data-c]{grid-template-columns:minmax(0,1fr)!important;justify-items:center;row-gap:20px}
.dcx [data-c]>*{max-width:100%}
.dcx [data-nav]{display:none!important}
.dcx [data-g4],.dcx [data-g5],.dcx [data-g6]{grid-template-columns:repeat(2,minmax(0,1fr))!important;row-gap:12px}
.dcx [data-scroll]{overflow-x:auto}
.dcx [data-h1]{white-space:normal!important}
}
@media (max-width:600px){.dcx [data-v]{zoom:.6}
.dcx [data-g4],.dcx [data-g5],.dcx [data-g6]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-h1]{font-size:30px!important;line-height:36px!important}
}
@media (max-width:1040px){.dcx [data-ragrid]{grid-template-columns:minmax(0,1fr)!important}
.dcx #studio [data-ranav]{display:none!important}
.dcx #studio>div{grid-template-columns:minmax(0,1fr)!important}
}

